<?php
namespace Tests\Feature\InternalGames;
use Tests\TestCase;
use Tests\Support\BlackjackFixture;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\{DB,Cache};
use App\Models\{CmsGame,CmsUserTransaction,InternalGameRound,InternalGameSession};
use App\Services\InternalGames\{InternalGamePlayService,InternalGameSessionService,InternalGameLedgerAuditService,InternalGameAuditService};
use Brick\Math\BigDecimal;
class MiniSlotFinancialTest extends TestCase {
 use DatabaseTransactions,BlackjackFixture;
 protected function setUp():void{parent::setUp();$this->setupBlackjack();(new \Database\Seeders\InternalSlotFamilySeeder)->run();}
 private function open(string $code='big-win',bool $demo=false):InternalGameSession{return app(InternalGameSessionService::class)->launch(CmsGame::where('reference_id','internal:'.$code)->firstOrFail(),$this->player,$demo,request());}
 private function svc():InternalGamePlayService{return app(InternalGamePlayService::class);}
 private function vector(string $code,array $symbols=['Blank','Blank','Blank']):void{config(['internal_games.games.'.$code.'.reel_strips'=>array_map(fn($s)=>[$s],$symbols)]);}
 private function spin($s,string $key='slot-spin',float $amount=10):array{return $this->svc()->spin($s->session_token,$this->player,$amount,$key);}
 private function reject(callable $fn,int $status=409):void{try{$fn();$this->fail('Expected '.$status);}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame($status,$e->getStatusCode());}}
 public function test_both_games_demo_and_real_original_multi_payline_results_history_and_wallet_trace():void{foreach(['big-win','mini-slot-classic']as $code)foreach([true,false]as $demo){$s=$this->open($code,$demo);$before=$this->financeHash();foreach([[['Blank','Blank','Blank'],0],[['BAR','BAR','BAR'],156],[['BAR','2xBAR','3xBAR'],25.8],[['7','Cherry','7'],510],[['Cherry','Cherry','Cherry'],6460]]as $index=>[$symbols,$win]){$this->vector($code,$symbols);$r=$this->spin($s,'vector-'.$index);$this->assertSame((float)$win,$r['winAmount']);$this->assertSame($win>0?'settled_win':'settled_loss',$r['status']);$this->assertCount(3,$r['result']['grid']);$tx=CmsUserTransaction::where('transactionId',$r['transactions']['bet'])->firstOrFail();$this->assertSame('internal_slot_bet',$tx->event_type);$this->assertSame($this->wallet->id,$tx->source_wallet_account_id);if($win>0){$credit=CmsUserTransaction::where('transactionId',$r['transactions']['win'])->firstOrFail();$this->assertSame($tx->transactionId,$credit->ref_transaction_id);}}$snap=$this->svc()->snapshot($s->session_token,$this->player);$this->assertCount(5,$snap['history']);$this->assertSame($r['roundId'],$snap['latestRound']['roundId']);$this->assertTrue(BigDecimal::of($snap['balanceExact'])->isEqualTo($r['balanceExact']));$this->assertNotSame($before,$this->financeHash());$this->reconcileBlackjack();}}
 public function test_replay_payload_conflict_invalid_stake_and_shared_session_lock():void{$s=$this->open();$this->vector('big-win');$a=$this->spin($s);$before=$this->financeHash();$this->assertSame($a,$this->spin($s));$this->reject(fn()=>$this->spin($s,'slot-spin',50));$this->reject(fn()=>$this->spin($s,'invalid-bet',11),422);$this->assertSame($before,$this->financeHash());$this->assertSame(1,InternalGameRound::where('game_code','big-win')->count());$held=Cache::lock('internal-slot-session:'.$s->id,15);$this->assertTrue($held->get());$this->reject(fn()=>$this->spin($s,'overlap-new'));$held->release();$this->assertSame($before,$this->financeHash());}
 public function test_refund_once_winning_demo_unfunded_and_borrowed_debit_eligibility():void{foreach([false,true]as $demo){$s=$this->open('big-win',$demo);$this->vector('big-win');$r=$this->spin($s);$this->assertSame('refunded',$this->svc()->refund($r['roundId'],'refund',$this->operator)['result']);$before=$this->financeHash();$this->assertSame('already_refunded',$this->svc()->refund($r['roundId'],'refund-again',$this->operator)['result']);$this->assertSame($before,$this->financeHash());$this->vector('big-win',['BAR','BAR','BAR']);$win=$this->spin($s,'win');$this->reject(fn()=>$this->svc()->refund($win['roundId'],'refund-win',$this->operator));}
  $s=$this->open();$this->vector('big-win');$one=$this->spin($s,'funded-one');$two=$this->spin($s,'funded-two');$row=InternalGameRound::where('round_id',$one['roundId'])->firstOrFail();$row->update(['debit_transaction_id'=>null]);$before=$this->financeHash();$this->reject(fn()=>$this->svc()->refund($one['roundId'],'unfunded',$this->operator));$row->update(['debit_transaction_id'=>InternalGameRound::where('round_id',$two['roundId'])->value('debit_transaction_id')]);$this->reject(fn()=>$this->svc()->refund($one['roundId'],'borrowed',$this->operator));$this->assertSame($before,$this->financeHash());$this->reconcileBlackjack();}
 public function test_large_balance_cent_integrity_without_changing_engine_math():void{
  // Deterministic fixture models a valid prior canonical ledger balance beyond JavaScript's exact-cent range.
  $large='90071992547409.91';$this->wallet->update(['available_balance'=>$large]);DB::table('cms_users')->where('id',$this->player->id)->update(['balance'=>$large]);DB::table('wallet_ledger_entries')->where('wallet_account_id',$this->wallet->id)->update(['amount'=>$large,'balance_after'=>$large]);DB::table('finance_manual_overrides')->where('cms_user_id',$this->player->id)->update(['amount'=>$large,'balance_after'=>$large]);
  foreach(['big-win','mini-slot-classic']as $code){$s=$this->open($code);$this->vector($code,['BAR','2xBAR','3xBAR']);$before=(string)$this->wallet->fresh()->available_balance;$r=$this->spin($s);$expected=BigDecimal::of($before)->minus('10')->plus('25.80');$this->assertTrue($expected->isEqualTo($r['balanceExact']));$this->assertTrue($expected->isEqualTo($this->wallet->fresh()->available_balance));$tx=CmsUserTransaction::where('transactionId',$r['transactions']['win'])->firstOrFail();$this->assertTrue($expected->isEqualTo($tx->exact_after_balance));$this->assertTrue(BigDecimal::of($before)->minus('10')->isEqualTo($tx->exact_before_balance));$this->reconcileBlackjack();}}
 public function test_engine_and_ledger_or_audit_failures_roll_back_all_economic_records():void{foreach(['ledger','audit']as $fault){$s=$this->open();$this->vector('big-win',['BAR','BAR','BAR']);$before=$this->financeHash();if($fault==='ledger'){$mock=\Mockery::mock(InternalGameLedgerAuditService::class);$mock->shouldReceive('recordDecimal')->andThrow(new \RuntimeException('Slot fault'));$this->app->instance(InternalGameLedgerAuditService::class,$mock);}else{$real=new InternalGameAuditService;$mock=\Mockery::mock(InternalGameAuditService::class)->makePartial();$mock->shouldReceive('logRound')->andReturnUsing(function($session,$round,$event,$payload=[],$status='info')use($real){if($event==='internal_game.spin.settled')throw new \RuntimeException('Slot fault');$real->logRound($session,$round,$event,$payload,$status);});$this->app->instance(InternalGameAuditService::class,$mock);}try{$this->spin($s,$fault);$this->fail('Expected rollback');}catch(\RuntimeException $e){$this->assertSame('Slot fault',$e->getMessage());}$this->assertSame($before,$this->financeHash());$this->assertSame(0,InternalGameRound::where('internal_game_session_id',$s->id)->count());$this->app->forgetInstance(InternalGameLedgerAuditService::class);$this->app->forgetInstance(InternalGameAuditService::class);}$this->reconcileBlackjack();}
 public function test_product_provider_country_browser_and_exact_insufficiency_boundaries():void{$this->vector('big-win');$s=$this->open();$before=$this->financeHash();foreach(['','internal-games']as $alias){$deny=\App\Models\CmsUserProductAccessOverride::create(['cms_user_id'=>$this->player->id,'product_key'=>'internal_games','provider_alias'=>$alias,'access_mode'=>'deny','reason'=>'Slot negative access']);$this->reject(fn()=>$this->spin($s),404);$deny->delete();}$policy=app(\App\Services\Restrictions\CentralRestrictionPolicyService::class)->settings();$policy['countries'][(string)$this->player->country_id]=['products'=>['casino'],'reason'=>'Synthetic country boundary'];$row=\App\SiteSettings::updateOrCreate(['key'=>\App\Services\Restrictions\CentralRestrictionPolicyService::SETTINGS_KEY],['value'=>json_encode($policy)]);$this->reject(fn()=>$this->spin($s),404);$row->delete();$this->browserRequest()->session()->regenerate();$this->reject(fn()=>$this->spin($s),403);$this->assertSame($before,$this->financeHash());$s=$this->open('big-win',true);for($i=0;$i<5;$i++)$last=$this->spin($s,'drain-'.$i,100);$this->assertSame('0.00',$last['balanceExact']);$before=$this->financeHash();$this->reject(fn()=>$this->spin($s,'empty-wallet',10));$this->assertSame($before,$this->financeHash());}
 public function test_owner_browser_wallet_expiry_maintenance_product_country_guards():void{$s=$this->open();$this->vector('big-win');$before=$this->financeHash();$other=$this->player->replicate();$other->username='slot_other';$other->email='slot-other@example.invalid';$other->save();$before=$this->financeHash();$this->reject(fn()=>$this->svc()->spin($s->session_token,$other,10,'foreign'),403);$s->update(['expires_at'=>now()->subSecond()]);$this->reject(fn()=>$this->spin($s),410);$s->update(['expires_at'=>now()->addMinute()]);$s->game->update(['is_maintenance'=>true]);$this->reject(fn()=>$this->spin($s),503);$s->game->update(['is_maintenance'=>false]);config(['product_wallets.products.internal_games.supported_assets'=>['USD']]);try{$this->spin($s);$this->fail('Unsupported wallet expected');}catch(\App\Services\Wallet\Exceptions\UnsupportedProductWalletException $e){$this->assertSame('unsupported_wallet',$e->details()['reason_code']);}$this->assertSame($before,$this->financeHash());}
}
